// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, random, interpolate } from '../remotionShim';


export type SonarVirusProps = Record<string, any>;

const SonarVirus: React.FC<SonarVirusProps> = ({
  backgroundColor = "#0b214a",
  transparentBackground = false,
  durationInSeconds = 10,
  radarBaseColor = "#061a3f",
  radarLineColor = "#26c750",
  radarSweepColor = "#46e05d",
  radarOuterRingColor = "#13448a",
  scanSpeed = 0.5,
  blipCount = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Center radar on screen since the virus is removed
  const radarRadius = height * 0.44;
  const radarCenterX = width / 2;
  const radarCenterY = height / 2;

  // Radar Animation Logic
  const sweepAngle = (frame * (360 / (fps * (1 / scanSpeed)))) % 360;

  // Pre-calculate static blip positions grouped into clusters
  const blips = useMemo(() => {
    const clusterCount = 3;
    const clusters = Array.from({ length: clusterCount }).map((_, cIdx) => {
      return {
        r: (0.25 + random(`cluster-r-${cIdx}`) * 0.5) * radarRadius,
        theta: random(`cluster-t-${cIdx}`) * 360,
      };
    });

    return Array.from({ length: blipCount }).map((_, i) => {
      const clusterIdx = i % clusterCount;
      const center = clusters[clusterIdx];
      
      const offsetR = (random(`blip-offr-${i}`) - 0.5) * radarRadius * 0.18;
      const offsetTheta = (random(`blip-offt-${i}`) - 0.5) * 40;

      const r = Math.max(0, Math.min(radarRadius * 0.9, center.r + offsetR));
      const theta = (center.theta + offsetTheta + 360) % 360;
      const size = random(`blip-s-${i}`) * 8 * s + 6 * s;

      return {
        id: i,
        r,
        theta,
        size,
      };
    });
  }, [blipCount, radarRadius, s]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* ----------------- RADAR SECTION ----------------- */}
      <div
        style={{
          position: "absolute",
          left: radarCenterX - radarRadius,
          top: radarCenterY - radarRadius,
          width: radarRadius * 2,
          height: radarRadius * 2,
          borderRadius: "50%",
          backgroundColor: radarBaseColor,
          border: `${16 * s}px solid ${radarOuterRingColor}`,
          boxSizing: "content-box",
          transform: `translate(-${16 * s}px, -${16 * s}px)`,
          overflow: "hidden",
        }}
      >
        {/* Detailed Concentric Radar Rings & Sections */}
        <svg width="100%" height="100%" viewBox="0 0 100 100" style={{ position: "absolute", top: 0, left: 0 }}>
          {/* Main circles */}
          <circle cx="50" cy="50" r="10" fill="none" stroke={radarLineColor} strokeWidth={0.3} strokeDasharray="1 1" opacity={0.5} />
          <circle cx="50" cy="50" r="20" fill="none" stroke={radarLineColor} strokeWidth={0.4} opacity={0.7} />
          <circle cx="50" cy="50" r="30" fill="none" stroke={radarLineColor} strokeWidth={0.3} strokeDasharray="1 1" opacity={0.5} />
          <circle cx="50" cy="50" r="40" fill="none" stroke={radarLineColor} strokeWidth={0.4} opacity={0.7} />
          <circle cx="50" cy="50" r="48" fill="none" stroke={radarLineColor} strokeWidth={0.6} opacity={0.9} />
          
          {/* Intermediary detailed sections */}
          <circle cx="50" cy="50" r="5" fill="none" stroke={radarLineColor} strokeWidth={0.2} opacity={0.3} />
          <circle cx="50" cy="50" r="15" fill="none" stroke={radarLineColor} strokeWidth={0.15} opacity={0.3} />
          <circle cx="50" cy="50" r="25" fill="none" stroke={radarLineColor} strokeWidth={0.15} opacity={0.3} />
          <circle cx="50" cy="50" r="35" fill="none" stroke={radarLineColor} strokeWidth={0.15} opacity={0.3} />
          <circle cx="50" cy="50" r="45" fill="none" stroke={radarLineColor} strokeWidth={0.15} opacity={0.3} />

          {/* Axes */}
          <line x1="50" y1="2" x2="50" y2="98" stroke={radarLineColor} strokeWidth={0.4} opacity={0.6} />
          <line x1="2" y1="50" x2="98" y2="50" stroke={radarLineColor} strokeWidth={0.4} opacity={0.6} />
          
          {/* Diagonal Guides */}
          <line x1="16" y1="16" x2="84" y2="84" stroke={radarLineColor} strokeWidth={0.25} strokeDasharray="1 2" opacity={0.4} />
          <line x1="16" y1="84" x2="84" y2="16" stroke={radarLineColor} strokeWidth={0.25} strokeDasharray="1 2" opacity={0.4} />
        </svg>

        {/* Sweep Gradient */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: "100%",
            height: "100%",
            borderRadius: "50%",
            background: `conic-gradient(from 0deg, transparent 0deg, transparent 270deg, ${radarSweepColor}80 360deg)`,
            transform: `rotate(${sweepAngle}deg)`,
            transition: "none",
          }}
        />

        {/* Clustered Blips */}
        {blips.map((blip) => {
          // Calculate sweep fade
          const diff = (sweepAngle - blip.theta + 360) % 360;
          const isActive = diff < 90;
          
          const opacity = isActive ? interpolate(diff, [0, 90], [1, 0.1]) : 0.1;
          const scale = isActive ? interpolate(diff, [0, 15, 90], [0.5, 1.2, 1], { extrapolateRight: "clamp" }) : 1;

          // CSS Angle to Cartesian
          const rad = (blip.theta * Math.PI) / 180;
          const bx = radarRadius + blip.r * Math.sin(rad);
          const by = radarRadius - blip.r * Math.cos(rad);

          return (
            <div
              key={blip.id}
              style={{
                position: "absolute",
                left: bx,
                top: by,
                width: blip.size,
                height: blip.size,
                marginLeft: -blip.size / 2,
                marginTop: -blip.size / 2,
                borderRadius: "50%",
                backgroundColor: radarSweepColor,
                opacity,
                transform: `scale(${scale})`,
                boxShadow: `0 0 ${10 * s}px ${radarSweepColor}`,
                transition: "none",
              }}
            />
          );
        })}
      </div>

    </AbsoluteFill>
  );
};

export default SonarVirus;